function orbit_is_dense(alpha, steps, tol):
  if alpha is an exact rational p/q (reduced):
    pts <- sorted set { (n*alpha) mod 1 : n = 0..q-1 }
    max_gap <- max consecutive gap around the circle
    return (max_gap < tol, max_gap, |pts|)
  else:  # alpha a generic real sample
    pts <- sorted set { (n*alpha) mod 1 : n = 0..steps-1 }
    max_gap <- max consecutive gap around the circle
    return (max_gap < tol, max_gap, |pts|)
